}

SELECT ?p ?name ?class ?ts WHERE {
  ?p brick:hasTag ?t .
  ?p rdfs:label ?name .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
  FILTER(?name = "Perimeter_top_ZN_3" OR REGEXT?name?name?")
}

SELECT ?p ?name ?class ?ts WHERE {
  ref:Zone_F3_Z04 brick:hasPoint ?p .
  ?p rdfs:label ?name .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?name ?ts WHERE {
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?z a brick:Zone .
  ?z brick:hasPoint ?p .
  ?p rdfs:label ?name .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?z ?p ?name ?ts WHERE {
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?z brick:hasPoint ?p .
  ?p rdfs:label ?name .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?name ?ts WHERE {
  ?z rdfs:label "Perimeter_top_ZN_3" .
  ?z ?pred ?p .
  ?p rdfs:label ?name .
  FILTER(?pred != rdf:type && ?pred != rdfs:label)
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?name ?class ?ts WHERE {
  ?p rdfs:label ?name .
  ?p a ?class .
  FILTER(CONTAINS(?name, "ZN_3"))
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 200

SELECT ?p ?name ?class ?ts WHERE {
  <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z04> ?pred ?p .
  FILTER(?pred != rdf:type && ?pred != rdfs:label)
  ?p rdfs:label ?name .
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?name ?class ?ts WHERE {
  ?p ?pred <http://buildgraph.org/BG_medium_office_2004_0000#Zone_F3_Z04> .
  ?p rdfs:label ?name .
  ?p a ?class .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?name ?class ?ts WHERE {
  ?p a brick:Air_Temperature .
  ?p rdfs:label ?name .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 10

SELECT ?class (COUNT(?p) AS ?n) WHERE {
  ?p a ?class .
  ?p rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "Temperature"))
} GROUP BY ?class

SELECT DISTINCT ?class WHERE {
  ?p a ?class .
  ?p rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "ZN_3"))
}

